import { Token } from '@uniswap/sdk-core'
import { useMemo } from 'react'
import { useQuery } from '@tanstack/react-query'
import { OnchainItemListOptionType, PoolOption } from 'uniswap/src/components/lists/items/types'
import { ProtocolVersion } from 'uniswap/src/data/graphql/uniswap-data-api/__generated__/types-and-hooks'
import { UniverseChainId } from 'uniswap/src/features/chains/types'
import { CurrencyInfo } from 'uniswap/src/features/dataApi/types'
import { getTokenLogoUrl } from 'uniswap/src/constants/tokenLogos'
import { fetchTopPoolsByTVL, V2PoolData, V3PoolData } from 'uniswap/src/features/routing/api/abstractSubgraph'

// Mapping from Abstract DEX tick spacing to fee tier (for display)
const TICK_SPACING_TO_FEE = {
  1: 100,      // 0.01%
  50: 500,     // 0.05%
  100: 500,    // 0.05%
  200: 3000,   // 0.3%
  2000: 10000, // 1%
} as const

function createCurrencyInfo(tokenData: {
  id: string
  symbol: string
  decimals: string
  name: string
}, chainId: UniverseChainId): CurrencyInfo {
  // Use the actual chainId for proper logo resolution
  const token = new Token(
    chainId,
    tokenData.id,
    parseInt(tokenData.decimals),
    tokenData.symbol,
    tokenData.name
  )

  return {
    currency: token,
    currencyId: `${chainId}-${tokenData.id.toLowerCase()}`,
    logoUrl: getTokenLogoUrl(tokenData.id),
  }
}

function transformV2PoolToPoolOption(pool: V2PoolData, chainId: UniverseChainId, gaugeAddress?: string): PoolOption {
  return {
    type: OnchainItemListOptionType.Pool,
    poolId: pool.id,
    chainId,
    token0CurrencyInfo: createCurrencyInfo(pool.token0, chainId),
    token1CurrencyInfo: createCurrencyInfo(pool.token1, chainId),
    protocolVersion: ProtocolVersion.V2,
    feeTier: pool.stable ? 500 : 3000, // V2: stable 0.05%, volatile 0.3%
    gaugeAddress,
  }
}

function transformV3PoolToPoolOption(pool: V3PoolData, chainId: UniverseChainId, gaugeAddress?: string): PoolOption {
  const tickSpacing = parseInt(pool.tickSpacing)
  const feeTier = TICK_SPACING_TO_FEE[tickSpacing as keyof typeof TICK_SPACING_TO_FEE] || 3000

  return {
    type: OnchainItemListOptionType.Pool,
    poolId: pool.id,
    chainId,
    token0CurrencyInfo: createCurrencyInfo(pool.token0, chainId),
    token1CurrencyInfo: createCurrencyInfo(pool.token1, chainId),
    protocolVersion: ProtocolVersion.V3,
    feeTier,
    gaugeAddress,
  }
}

export function useTrendingPoolsOptions(
  limit: number = 15,
  chainFilter: UniverseChainId | null = null
): {
  data: PoolOption[] | undefined
  loading: boolean
  error: any
  refetch: () => void
} {
  // Use Abstract mainnet as default if no chain filter provided
  const chainId = chainFilter || UniverseChainId.Mainnet

  const {
    data: poolsData,
    isLoading,
    error,
    refetch,
  } = useQuery({
    queryKey: ['trending-pools', limit, chainId],
    queryFn: () => fetchTopPoolsByTVL(limit),
    staleTime: 5 * 60 * 1000, // 5 minutes
    refetchInterval: 5 * 60 * 1000, // Refetch every 5 minutes
  })

  const poolOptions = useMemo(() => {
    if (!poolsData) return undefined

    const allPools: PoolOption[] = []

    // Transform V2 pools
    poolsData.v2Pools.forEach((pool) => {
      const gaugeAddress = poolsData.gauges.get(pool.id.toLowerCase())
      allPools.push(transformV2PoolToPoolOption(pool, chainId, gaugeAddress))
    })

    // Transform V3 pools
    poolsData.v3Pools.forEach((pool) => {
      const gaugeAddress = poolsData.gauges.get(pool.id.toLowerCase())
      allPools.push(transformV3PoolToPoolOption(pool, chainId, gaugeAddress))
    })

    // Sort by TVL (V2: reserveUSD, V3: totalValueLockedUSD)
    // Since we already get them sorted from the subgraph, we can just slice to the limit
    return allPools.slice(0, limit)
  }, [poolsData, chainId, limit])

  return {
    data: poolOptions,
    loading: isLoading,
    error,
    refetch,
  }
}