import { Token } from '@uniswap/sdk-core'
import { createContext, ReactNode, useContext, useMemo } from 'react'
import { useDispatch, useSelector } from 'react-redux'

interface UserTokensContextType {
  userAddedTokens: Token[]
  addUserToken: (token: Token) => void
  removeUserToken: (chainId: number, address: string) => void
}

const UserTokensContext = createContext<UserTokensContextType | undefined>(undefined)

export function UserTokensContextProvider({ children }: { children: ReactNode }): JSX.Element {
  const dispatch = useDispatch()
  
  // Get serialized tokens from Redux state - we need to import these types
  const serializedTokens = useSelector((state: any) => state.user?.tokens)
  
  // Convert serialized tokens back to Token instances
  const userAddedTokens: Token[] = useMemo(() => {
    const tokens: Token[] = []
    if (serializedTokens) {
      Object.values(serializedTokens).forEach((chainTokens: any) => {
        if (chainTokens) {
          Object.values(chainTokens).forEach((serializedToken: any) => {
            if (serializedToken) {
              // Create Token instance from serialized data
              const token = new Token(
                serializedToken.chainId,
                serializedToken.address,
                serializedToken.decimals,
                serializedToken.symbol,
                serializedToken.name
              )
              tokens.push(token)
            }
          })
        }
      })
    }
    return tokens
  }, [serializedTokens])

  const addUserToken = (token: Token) => {
    dispatch({
      type: 'user/addToken',
      payload: {
        token: {
          chainId: token.chainId,
          address: token.address,
          decimals: token.decimals,
          symbol: token.symbol,
          name: token.name,
        }
      }
    })
  }

  const removeUserToken = (chainId: number, address: string) => {
    dispatch({
      type: 'user/removeToken',
      payload: { chainId, address }
    })
  }

  return (
    <UserTokensContext.Provider value={{ userAddedTokens, addUserToken, removeUserToken }}>
      {children}
    </UserTokensContext.Provider>
  )
}

export function useUserTokens(): UserTokensContextType {
  const context = useContext(UserTokensContext)
  if (context === undefined) {
    throw new Error('useUserTokens must be used within a UserTokensContextProvider')
  }
  return context
}