import { useAccount, useConnectorClient } from 'wagmi'
import { useMemo, useEffect, useState } from 'react'
import { isAbstractChain } from 'uniswap/src/constants/abstractContracts'

export interface Eip5792Support {
  supported: boolean
  isLoading: boolean
}

/**
 * Hook to detect EIP-5792 wallet capabilities using wallet_getCapabilities
 * @param chainId - The chain ID to check support for
 * @returns object with supported boolean and isLoading state
 */
export function useEip5792Support(chainId?: number): Eip5792Support {
  const { address } = useAccount()
  const { data: client } = useConnectorClient()
  const [capabilities, setCapabilities] = useState<any>(undefined) // Use undefined as initial state
  const [hasChecked, setHasChecked] = useState(false)

  useEffect(() => {
    const getCapabilities = async () => {
      // Only check once per wallet connection
      if (!client || !address || !chainId || !isAbstractChain(chainId) || hasChecked) {
        return
      }

      setHasChecked(true)
      try {
        // Use the standard EIP-5792 method to get wallet capabilities
        const chainHex = `0x${chainId.toString(16)}`
        const caps = await client.request({
          method: 'wallet_getCapabilities',
          params: [address]
        })
        
        console.log('[EIP-5792] Capabilities received:', caps)
        setCapabilities(caps)
      } catch (error: any) {
        // Silently handle wallets that don't support EIP-5792
        // This is expected for most wallets currently
        if (error.code === -32601 || error.message?.includes('not found')) {
          // Method not found - wallet doesn't support EIP-5792
          setCapabilities({})
        } else {
          // Unexpected error - log it once
          console.warn('EIP-5792 capability check failed:', error.message)
          setCapabilities({})
        }
      }
    }

    getCapabilities()
  }, [client, address, chainId, hasChecked])

  // Reset check flag when wallet changes
  useEffect(() => {
    setHasChecked(false)
    setCapabilities(undefined)
  }, [address, client])

  return useMemo(() => {
    // Only enable batching for Abstract chains
    if (!chainId || !isAbstractChain(chainId)) {
      return { supported: false, isLoading: false }
    }

    // Still checking capabilities (undefined = not checked yet)
    if (capabilities === undefined) {
      return { supported: false, isLoading: true }
    }

    const chainHex = `0x${chainId.toString(16)}`

    // Check capabilities for this specific chain or global capabilities (0x0)
    const chainCaps = capabilities?.[chainHex] || capabilities?.['0x0']

    // Check for atomic capability with supported status
    const atomicCapability = chainCaps?.atomic
    const supportsAtomic = atomicCapability?.status === 'supported'

    console.log('[EIP-5792] Capability check:', {
      chainHex,
      chainCaps,
      atomicCapability,
      supportsAtomic,
      allCapabilities: capabilities,
    })

    return { supported: supportsAtomic, isLoading: false }
  }, [chainId, capabilities])
}

